ECS = {}

-- call this to (re)initialize per-player settings
InitializeECS = function()
	ECS.Mode = "Warmup"
	ECS.IsPractice = false
	ECS.BreakTimer=(15 * 60)
	ECS.SetTimer=(60 * 60)
	ECS.SpeedAttemptNumber = 0
	ECS.TimeToRemoveFromBreakTimer = 0

	ECS.Player = {
		ProfileName=nil,
		Relics={},
		-- Use AddPlayedSongs to append to this table which will keep this table
		-- sorted in descending order of points.
		SongsPlayed={},
		-- Also updated in AddPlayedSongs below.
		ConsecutivePasses = 0,
		StethoscopeActive = false,
		MixTapesRandomSong = nil,
		WrapperActive = false,
		EternalYouthActive = false,

		TotalMarathonPoints=0,
		MarathonRateMod=1,
	}
end

-- Used for rate mod adjustment
local ForcesOneRate = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Medal of Freedom" or name == "Chilsung Cider") then
			return true
		end
	end
	return false
end

-- Used for life 4 adjustment
local ForcesLifeFour = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Medal of Freedom" or name == "IV Bag") then
			return true
		end
	end
	return false
end

local BowEquipped = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Short Bow" or name == "Composite Bow" or name == "Long Bow" or name == "Twisted Bow" or
			name == "Bowzee" or name == "Rosenbogen" or name == "Rosenbogen +1" or name == "Rosenbogen +2") then
			return true
		end
	end
	return false
end

local ArrowEquipped = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Stone Arrow" or name == "Bronze Arrow" or name == "Mythril Arrow" or name == "Dragon Arrow" or
	      name == "Double Stone Arrow" or name == "Double Bronze Arrow" or name == "Double Mythril Arrow") then
			return true
		end
	end
	return false
end

local GunEquipped = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Exeter") then
			return true
		end
	end
	return false
end

local BulletEquipped = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Bullet" or name == "Pulse Ammo" or name == "Chrono Bullet") then
			return true
		end
	end
	return false
end

local UsingTuucsCrackers = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Tuuc's Crackers") then
			return true
		end
	end
	return false
end

local UsingTuucsJams = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Tuuc's Jams") then
			return true
		end
	end
	return false
end

local UsingGameCartridge = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Game Cartridge") then
			return true
		end
	end
	return false
end

