		effect="Lv. 2 RP Bonus|RP for this relic is calculated using chart block level +1",
		is_consumable=false,
		is_marathon=false,
		img="twinnedtarge.png",
		action=function(relics_used) end,
		score=function(ecs_player, song_info, song_data, relics_used, ap, score)
			local max_division_rp = 1000 * (1 + (song_info.MaxBlockLevel-song_info.MinBlockLevel))
			return math.floor((song_data.rp + 1000)/(max_division_rp/1000) * 0.2)
		end,
	},
	{
		id=188,
		name="Zulfiqar",
		desc="Heirloom blade with a double tip.  Its origins are lost to oral tradition, but merely handling this sword is enough to grasp that it holds a mysterious power.",
		effect="+500 BP for Rank 1 on Lifetime Song WS|+BP based on Lifetime Song WS for Rank 2 and below (Max 350)",
		is_consumable=false,
		is_marathon=false,
		img="zulfiqar.png",
		action=function(relics_used) end,
		score=function(ecs_player, song_info, song_data, relics_used, ap, score)
			-- Determine Rank 1 JP by checking every player
			local all_ws_amounts = {}
			for name, player in pairs(ECS.Players) do
				all_ws_amounts[#all_ws_amounts + 1] = player.lifetime_ws
			end
			table.sort(all_ws_amounts)

			local max_jp = all_ws_amounts[#all_ws_amounts]
			if max_jp == nil then return 0 end

			-- We need the 2nd highest as well for those that weren't rank 1
			local second_highest = nil
			for i = #all_ws_amounts, 1, -1 do
				if all_ws_amounts[i] < max_jp then
					second_highest = all_ws_amounts[i]
					break
				end
			end

			if max_jp == ecs_player.lifetime_ws then
				return 500
			else
				local second_highest = all_ws_amounts[#all_ws_amounts-1]
				if second_highest == nil then return 0 end
				return math.floor(350 * (ecs_player.lifetime_ws / second_highest))
			end
		end,
	},
